1. include!("../src/main.rs");
2. 
3. #[cfg(test)]
4. mod tests {
5.     use super::cli_config::{App, DecodeArgs, EncodeArgs};
6.     use super::translators::decode::{decode_token, decoding_key_from_secret, OutputFormat};
7.     use super::translators::encode::{encode_token, encoding_key_from_secret};
8.     use base64::decode as base64_decode;
9.     use chrono::{Duration, TimeZone, Utc};
10.     use clap::{FromArgMatches, IntoApp};
11.     use jsonwebtoken::{Algorithm, DecodingKey, EncodingKey, TokenData};
12.     use serde_json::from_value;
13. 
14.     #[test]
15.     fn encodes_a_token() {
16.         let exp = (Utc::now() + Duration::minutes(60)).timestamp();
17.         let nbf = Utc::now().timestamp();
18.         let encode_matcher = App::command()
19.             .try_get_matches_from(vec![
20.                 "jwt",
21.                 "encode",
22.                 "-S",
23.                 "1234567890",
24.                 "-A",
25.                 "HS256",
26.                 "-a",
27.                 "yolo",
28.                 "-e",
29.                 &exp.to_string(),
30.                 "-i",
31.                 "yolo-service",
32.                 "-k",
33.                 "1234",
34.                 "-n",
35.                 &nbf.to_string(),
36.                 "--jti",
37.                 "yolo-jti",
38.                 "-P",
39.                 "this=that",
40.                 "-P",
41.                 "number=10",
42.                 "-P",
43.                 "array=[1, 2, 3]",
44.                 "-P",
45.                 "object={\"foo\": \"bar\"}",
46.                 "-s",
47.                 "yolo-subject",
48.                 "{\"test\":\"json value\",\"bool\":true,\"json_number\":1}",
49.             ])
50.             .unwrap();
51.         let encode_matches = encode_matcher.subcommand_matches("encode").unwrap();
